<?php
require_once __DIR__.'/inc/connect.php';
require_once __DIR__.'/inc/auth.php';
if(!in_array((int)$_SESSION['log_role'],[1,2,3],true)){http_response_code(403);exit('Not authorized.');}
$role=(int)$_SESSION['log_role'];$user=(int)$_SESSION['u_id'];$facility=(int)($_SESSION['facility_id']??0);
$scope='';$args=[];
if($role===2){$scope=' AND m.facility_id=?';$args[]=$facility;}
elseif($role===3){$scope=' AND m.chw_id=?';$args[]=$user;}
$error='';$calls=[];$callbacks=[];$eligible=[];$stats=[];$byPurpose=[];$byDate=[];
try{
 $q=$db->prepare("SELECT c.call_id,c.purpose,c.status,c.language,c.started_at,c.answered_at,c.ended_at,c.duration_seconds,c.failure_reason,c.created_at,m.mother_id,m.f_name,m.l_name FROM mcare_outbound_calls c JOIN tbl_mothers m ON m.mother_id=c.mother_id WHERE 1=1$scope ORDER BY c.call_id DESC LIMIT 100");$q->execute($args);$calls=$q->fetchAll(PDO::FETCH_ASSOC);
 $q=$db->prepare("SELECT b.callback_id,b.requested_at,b.status,m.mother_id,m.f_name,m.l_name,m.phone FROM mcare_call_back_requests b JOIN tbl_mothers m ON m.mother_id=b.mother_id WHERE b.status='pending'$scope ORDER BY b.requested_at LIMIT 100");$q->execute($args);$callbacks=$q->fetchAll(PDO::FETCH_ASSOC);
 $q=$db->prepare("SELECT m.mother_id,m.f_name,m.l_name,m.phone,co.consented_at FROM tbl_mothers m JOIN mcare_call_consent co ON co.mother_id=m.mother_id AND co.consent_status='granted' WHERE m.is_active=1 AND m.phone IS NOT NULL AND NOT EXISTS(SELECT 1 FROM mcare_outbound_calls c WHERE c.mother_id=m.mother_id AND (c.status IN ('pending','queued','initiating','ringing','answered','in_progress') OR c.created_at>=DATE_SUB(NOW(),INTERVAL 24 HOUR)))$scope ORDER BY m.f_name,m.l_name LIMIT 200");$q->execute($args);$eligible=$q->fetchAll(PDO::FETCH_ASSOC);
 $q=$db->prepare("SELECT COUNT(*) total,SUM(c.status='completed') completed,SUM(c.status IN ('pending','initiating','ringing','answered','in_progress')) active,SUM(c.status IN ('failed','busy','no_answer')) unsuccessful,ROUND(AVG(c.duration_seconds),1) avg_duration FROM mcare_outbound_calls c JOIN tbl_mothers m ON m.mother_id=c.mother_id WHERE c.created_at>=DATE_SUB(NOW(),INTERVAL 30 DAY)$scope");$q->execute($args);$stats=$q->fetch(PDO::FETCH_ASSOC)?:[];
 $q=$db->prepare("SELECT c.purpose,COUNT(*) total FROM mcare_outbound_calls c JOIN tbl_mothers m ON m.mother_id=c.mother_id WHERE c.created_at>=DATE_SUB(NOW(),INTERVAL 30 DAY)$scope GROUP BY c.purpose ORDER BY total DESC");$q->execute($args);$byPurpose=$q->fetchAll(PDO::FETCH_ASSOC);
 $q=$db->prepare("SELECT DATE(c.created_at) call_date,COUNT(*) total,SUM(c.status='completed') completed FROM mcare_outbound_calls c JOIN tbl_mothers m ON m.mother_id=c.mother_id WHERE c.created_at>=DATE_SUB(NOW(),INTERVAL 14 DAY)$scope GROUP BY DATE(c.created_at) ORDER BY call_date DESC");$q->execute($args);$byDate=$q->fetchAll(PDO::FETCH_ASSOC);
}catch(Throwable $e){$error='Outbound-call tables are not available. Apply migrations/012_outbound_calling.sql after the database service is running.';}
$page_title='Outbound call management';$breadcrumb=[['Home','home'],['Outbound calls','']];include 'inc/links.php';include 'inc/header.php';$e=static fn($x)=>htmlspecialchars((string)$x,ENT_QUOTES,'UTF-8');
?>
<div class="inner-wrapper"><?php include 'inc/sidebar.php';?><section role="main" class="content-body"><?php include 'inc/inner-header.php';?>
<main class="container-fluid"><h1>Outbound call management</h1><p>Calls are initiated through the configured Asterisk route. Asterisk events, rather than request submission, set ringing and answer states.</p>
<?php if($error):?><div class="alert alert-warning"><?=$e($error)?></div><?php else:?>
<div class="row"><div class="col-sm-3"><section class="panel"><div class="panel-body"><strong>Calls · 30 days</strong><h3><?=(int)($stats['total']??0)?></h3></div></section></div><div class="col-sm-3"><section class="panel"><div class="panel-body"><strong>Completed</strong><h3><?=(int)($stats['completed']??0)?></h3></div></section></div><div class="col-sm-3"><section class="panel"><div class="panel-body"><strong>Active</strong><h3><?=(int)($stats['active']??0)?></h3></div></section></div><div class="col-sm-3"><section class="panel"><div class="panel-body"><strong>Busy / no answer / failed</strong><h3><?=(int)($stats['unsuccessful']??0)?></h3></div></section></div></div>
<div class="row"><div class="col-sm-6"><section class="panel"><div class="panel-body"><strong>Average answered-call duration</strong><p><?=htmlspecialchars((string)($stats['avg_duration']??'—'),ENT_QUOTES,'UTF-8')?> sec</p></div></section></div><div class="col-sm-6"><section class="panel"><div class="panel-body"><strong>Call completion rate</strong><p><?=(int)($stats['total']??0)>0?number_format(100*(int)($stats['completed']??0)/(int)$stats['total'],1):'0.0'?>%</p></div></section></div></div>
<section class="panel"><header class="panel-heading"><h2 class="panel-title">Queue a small call batch</h2></header><div class="panel-body"><p>Only active profiles with recorded call consent are listed. Select up to 20; the queue worker places calls within the configured concurrency limit.</p><form id="mcare-bulk-calls"><input type="hidden" name="_csrf" value="<?=$e($_SESSION['csrf_token'])?>"><div class="row"><div class="col-sm-4"><label>Call purpose</label><select class="form-control" name="purpose"><option value="test">Authorized test call</option><option value="anc_followup">ANC follow-up</option><option value="appointment_reminder">Appointment reminder</option><option value="postnatal_followup">Postnatal follow-up</option><option value="missed_appointment">Missed appointment</option><option value="medication_reminder">Medication reminder</option><option value="worker_followup">Care-team follow-up</option></select></div><div class="col-sm-3"><label>Queue priority (1 highest)</label><select class="form-control" name="priority"><option value="5">Normal</option><option value="3">High</option><option value="1">Highest</option></select></div><div class="col-sm-8"><label>Consented recipients</label><div class="table-responsive" style="max-height:260px;overflow:auto"><table class="table table-condensed"><thead><tr><th>Select</th><th>Woman</th><th>Phone</th><th>Consent recorded</th></tr></thead><tbody><?php foreach($eligible as $m):?><tr><td><input type="checkbox" name="mother_ids[]" value="<?=(int)$m['mother_id']?>" aria-label="Select <?=$e($m['f_name'].' '.$m['l_name'])?>"></td><td><a href="mother_profile?id=<?=(int)$m['mother_id']?>"><?=$e($m['f_name'].' '.$m['l_name'])?></a></td><td><?=$e($m['phone'])?></td><td><?=$e($m['consented_at'])?></td></tr><?php endforeach;?><?php if(!$eligible):?><tr><td colspan="4">No eligible recipients in your assigned scope.</td></tr><?php endif;?></tbody></table></div></div></div><button class="btn btn-primary" type="submit">Queue selected calls</button><span id="mcare-bulk-result" aria-live="polite"></span></form></div></section>
<section class="panel"><header class="panel-heading"><h2 class="panel-title">Call-back requests</h2></header><div class="panel-body table-responsive"><table class="table"><thead><tr><th>Woman</th><th>Phone</th><th>Requested</th><th>Action</th></tr></thead><tbody><?php foreach($callbacks as $c):?><tr><td><a href="mother_profile?id=<?=(int)$c['mother_id']?>"><?=$e($c['f_name'].' '.$c['l_name'])?></a></td><td><?=$e($c['phone'])?></td><td><?=$e($c['requested_at'])?></td><td><button class="btn btn-success btn-xs callback-status" data-id="<?=(int)$c['callback_id']?>" data-status="contacted">Mark contacted</button> <button class="btn btn-default btn-xs callback-status" data-id="<?=(int)$c['callback_id']?>" data-status="cancelled">Dismiss</button></td></tr><?php endforeach;?><?php if(!$callbacks):?><tr><td colspan="4">No pending call-back requests.</td></tr><?php endif;?></tbody></table></div></section>
<section class="panel"><header class="panel-heading"><h2 class="panel-title">Recent outbound calls</h2></header><div class="panel-body table-responsive"><table class="table"><thead><tr><th>Call ID</th><th>Woman</th><th>Purpose</th><th>Language</th><th>Status</th><th>Started</th><th>Answered</th><th>Duration</th><th>Failure</th></tr></thead><tbody><?php foreach($calls as $c):?><tr><td>#<?=(int)$c['call_id']?></td><td><a href="mother_profile?id=<?=(int)$c['mother_id']?>"><?=$e($c['f_name'].' '.$c['l_name'])?></a></td><td><?=$e($c['purpose'])?></td><td><?=$e(strtoupper($c['language']))?></td><td><?=$e($c['status'])?></td><td><?=$e($c['started_at']?:$c['created_at'])?></td><td><?=$e($c['answered_at']?:'—')?></td><td><?=$e($c['duration_seconds']??'—')?></td><td><?=$e($c['failure_reason']?:'—')?></td></tr><?php endforeach;?><?php if(!$calls):?><tr><td colspan="9">No calls yet.</td></tr><?php endif;?></tbody></table></div></section>
<div class="row"><div class="col-md-6"><section class="panel"><header class="panel-heading"><h2 class="panel-title">Calls by purpose · 30 days</h2></header><div class="panel-body"><table class="table table-condensed"><thead><tr><th>Purpose</th><th>Calls</th></tr></thead><tbody><?php foreach($byPurpose as $x):?><tr><td><?=$e($x['purpose'])?></td><td><?=(int)$x['total']?></td></tr><?php endforeach;?><?php if(!$byPurpose):?><tr><td colspan="2">No calls in this period.</td></tr><?php endif;?></tbody></table></div></section></div><div class="col-md-6"><section class="panel"><header class="panel-heading"><h2 class="panel-title">Calls by date · 14 days</h2></header><div class="panel-body"><table class="table table-condensed"><thead><tr><th>Date</th><th>Total</th><th>Completed</th></tr></thead><tbody><?php foreach($byDate as $x):?><tr><td><?=$e($x['call_date'])?></td><td><?=(int)$x['total']?></td><td><?=(int)$x['completed']?></td></tr><?php endforeach;?><?php if(!$byDate):?><tr><td colspan="3">No calls in this period.</td></tr><?php endif;?></tbody></table></div></section></div></div>
<?php endif;?></main>
<script>
document.addEventListener('click',async e=>{const b=e.target.closest('.callback-status');if(!b)return;b.disabled=true;try{const r=await fetch('outbound_call_api.php',{method:'POST',credentials:'same-origin',headers:{'Content-Type':'application/x-www-form-urlencoded;charset=UTF-8'},body:new URLSearchParams({_csrf:<?=json_encode($_SESSION['csrf_token'])?>,action:'callback_resolve',callback_id:b.dataset.id,status:b.dataset.status})}),d=await r.json();if(!r.ok||!d.ok)throw new Error(d.error||'Update failed');location.reload();}catch(x){alert(x.message);b.disabled=false;}});document.getElementById('mcare-bulk-calls').addEventListener('submit',async e=>{e.preventDefault();const ids=e.currentTarget.querySelectorAll('[name="mother_ids[]"]:checked');if(ids.length<1||ids.length>20){document.getElementById('mcare-bulk-result').textContent=' Select between 1 and 20 women.';return;}const b=e.submitter;b.disabled=true;try{const f=new FormData(e.currentTarget);f.append('action','bulk');const r=await fetch('outbound_call_api.php',{method:'POST',credentials:'same-origin',headers:{'Content-Type':'application/x-www-form-urlencoded;charset=UTF-8'},body:new URLSearchParams(f)}),d=await r.json();if(!r.ok||!d.ok)throw new Error(d.error||'Batch could not be queued');document.getElementById('mcare-bulk-result').textContent=' '+d.message;setTimeout(()=>location.reload(),1500);}catch(x){document.getElementById('mcare-bulk-result').textContent=' '+x.message;}finally{b.disabled=false;}});
</script>
</section></div><?php include 'inc/footer.php';include 'inc/scripts.php';?>
